<script setup lang="ts">
import{computed,onMounted,onUnmounted,ref,watch}from'vue';
import{distortionPlan,transformCorners,quadBounds,carriedCorners,convexQuad}from'../../../packages/comp-bridge/distort.mjs';
import{createPreviewRenderer,makeCanvas}from'../../../packages/editor-adapter/render';
import{parityMessages}from'./parity-labels';
import{localizedMessages}from'../../../packages/locales';
import type{Language,ViewerProject,OpenResult}from'./types';
const props=defineProps<{language:Language;project:ViewerProject;ids:string[];target:'content'|'mask';commit:(op:Record<string,unknown>,owner:{id:string;revision:string})=>Promise<OpenResult>}>(),emit=defineEmits(['close','running']),t=computed(()=>parityMessages[props.language]),owner={id:props.project.id,revision:props.project.revision};
const original=JSON.parse(JSON.stringify({...props.project,selection:undefined,locks:undefined})),plan=distortionPlan(original.analysis.rows,props.ids,props.target),initial=transformCorners(plan.box),corners=ref<number[][]>(initial.map(p=>[...p])),svg=ref<SVGSVGElement>(),canvas=ref<HTMLCanvasElement>(),busy=ref(true),computing=ref(true),applying=ref(false),error=ref(''),selected=ref(0),showGrid=ref(true),view=ref({x:0,y:0,w:1,h:1}),past=ref<number[][][]>([]),future=ref<number[][][]>([]);
const copy=()=>corners.value.map(p=>[...p]),valid=computed(()=>{try{quadBounds(corners.value);return true;}catch{return false;}}),radius=computed(()=>Math.max(.02,view.value.w/115));
let live=true,worker:Worker|undefined,preview:ReturnType<typeof createPreviewRenderer>|undefined,inFlight=false,pending=false,timer:ReturnType<typeof setTimeout>|undefined,debounce:ReturnType<typeof setTimeout>|undefined,drag:{index?:number;before:number[][];x:number;y:number;view:{x:number;y:number;w:number;h:number}}|undefined;
const sources=new Map<string,HTMLCanvasElement>();
function fit(){const points=[...corners.value,[0,0],[original.manifest.width,original.manifest.height]],x=Math.min(...points.map(p=>p[0])),y=Math.min(...points.map(p=>p[1])),w=Math.max(...points.map(p=>p[0]))-x,h=Math.max(...points.map(p=>p[1]))-y,pad=Math.max(w,h)*.12;view.value={x:x-pad,y:y-pad,w:Math.max(1,w+pad*2),h:Math.max(1,h+pad*2)};}
fit();
function remember(before:number[][]){if(JSON.stringify(before)===JSON.stringify(corners.value))return;past.value.push(before);if(past.value.length>64)past.value.shift();future.value=[];}
function history(action:string){if(applying.value||drag||document.activeElement?.closest('input,textarea,select,[contenteditable]'))return;const from=action==='undo'?past:future,to=action==='undo'?future:past;if(!from.value.length)return;to.value.push(copy());corners.value=from.value.pop()!;}
const stopUndo=window.editor.onCommand('undo',()=>history('undo')),stopRedo=window.editor.onCommand('redo',()=>history('redo'));
function coordinate(index:number,axis:number,event:Event){const before=copy();corners.value[index][axis]=Number((event.target as HTMLInputElement).value);remember(before);}
function reset(){const before=copy();corners.value=initial.map(p=>[...p]);remember(before);fit();}
function point(event:PointerEvent|WheelEvent){const matrix=svg.value?.getScreenCTM();if(!matrix)return[0,0];const p=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse());return[p.x,p.y];}
function start(event:PointerEvent,index?:number){if(busy.value||applying.value||event.button!==0&&event.button!==1)return;event.preventDefault();svg.value?.focus();svg.value?.setPointerCapture(event.pointerId);if(index!==undefined)selected.value=index;drag={index,before:copy(),x:event.clientX,y:event.clientY,view:{...view.value}};}
function move(event:PointerEvent){if(!drag)return;if(drag.index!==undefined)corners.value[drag.index]=point(event);else{const a=new DOMPoint(drag.x,drag.y).matrixTransform(svg.value!.getScreenCTM()!.inverse()),b=point(event);view.value={...view.value,x:view.value.x+a.x-b[0],y:view.value.y+a.y-b[1]};drag.x=event.clientX;drag.y=event.clientY;}}
function end(){if(drag)remember(drag.before);drag=undefined;}
function wheel(event:WheelEvent){if(drag||applying.value)return;const p=point(event),amount=event.deltaY>0?1.2:1/1.2,w=Math.min(2e6,Math.max(.1,view.value.w*amount)),factor=w/view.value.w;view.value={x:p[0]-(p[0]-view.value.x)*factor,y:p[1]-(p[1]-view.value.y)*factor,w,h:view.value.h*factor};}
function key(event:KeyboardEvent){if(event.isComposing)return;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close();return;}if((event.target as HTMLElement).closest('input,select,textarea,button,[contenteditable]'))return;if(event.key==='Enter'){event.preventDefault();void apply();return;}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)&&!applying.value){const before=copy(),axis=event.key==='ArrowLeft'||event.key==='ArrowRight'?0:1;corners.value[selected.value][axis]+=(event.shiftKey?10:1)*(event.key==='ArrowLeft'||event.key==='ArrowUp'?-1:1);remember(before);event.preventDefault();}}
function close(){if(!applying.value)emit('close');}
function release(){for(const surface of sources.values())surface.width=surface.height=1;sources.clear();}
function fail(code?:string){error.value=(localizedMessages(props.language,'windows').errors as Record<string,string>)[code??'invalid']??t.value.failed;computing.value=false;inFlight=false;clearTimeout(timer);}
function refresh(){clearTimeout(debounce);debounce=undefined;if(!live||busy.value||!valid.value||!worker)return;if(inFlight){pending=true;return;}pending=false;inFlight=true;computing.value=true;error.value='';timer=setTimeout(()=>{worker?.terminate();preview?.dispose();fail();},30000);worker.postMessage({action:'preview',corners:copy()});}
watch(corners,()=>{computing.value=true;clearTimeout(debounce);debounce=setTimeout(refresh,60);},{deep:true});
const grid=computed(()=>{if(!showGrid.value||!valid.value)return[];if(!convexQuad(corners.value))return[[corners.value[0],corners.value[2]]];const lines:number[][][]=[];for(let i=1;i<4;i++){const n=i/4;for(const box of[{origin:[n,0],size:[.0001,1]},{origin:[0,n],size:[1,.0001]}]){const points=carriedCorners({...box,rotation:0,flipX:false,flipY:false,sampling:'Nearest'},{origin:[0,0],size:[1,1],rotation:0},corners.value);lines.push([points[0],box.size[0]===1?points[1]:points[3]]);}}return lines;});
async function bitmap(file:string){const response=await fetch(props.project.urls['images/'+file]);if(!response.ok)throw new Error('asset');const image=await createImageBitmap(await response.blob());try{const factor=Math.min(1,1536/Math.max(image.width,image.height)),surface=makeCanvas(Math.max(1,Math.round(image.width*factor)),Math.max(1,Math.round(image.height*factor)));try{const context=surface.getContext('2d')!;context.drawImage(image,0,0,surface.width,surface.height);return context.getImageData(0,0,surface.width,surface.height);}finally{surface.width=surface.height=1;}}finally{image.close();}}
onMounted(async()=>{emit('running',true);try{
 const assets:Record<string,any>={};let bytes=0;const files=new Set<string>();for(const row of plan.rows){if(props.target==='content'&&row.imageFile)files.add(row.imageFile);if(row.maskFile)files.add(row.maskFile);}
 for(const file of files){if(!live)return;const image=await bitmap(file);bytes+=image.data.byteLength;if(bytes>64*1024**2)throw new Error('limit');assets[file]={width:image.width,height:image.height,data:image.data};}
 if(!live)return;preview=createPreviewRenderer(sources);worker=new Worker(new URL('./distort-worker.ts',import.meta.url),{type:'module'});worker.onerror=()=>fail();worker.onmessage=async event=>{
  if(!live)return;if(event.data.ready){clearTimeout(timer);busy.value=false;refresh();return;}if(event.data.error){fail(event.data.error);return;}
  try{const candidate=JSON.parse(JSON.stringify(original)),replacements=new Map(event.data.result.map((item:any)=>[item.row.id,item.row]));release();
   for(const item of event.data.result)for(const field of['image','mask'])if(item[field]){const image=item[field],surface=makeCanvas(image.width,image.height),file=`${item.row.id}.${field}.distort-preview.png`,url=`distort-preview:${file}`;surface.getContext('2d')!.putImageData(new ImageData(new Uint8ClampedArray(image.data),image.width,image.height),0,0);item.row[field==='image'?'imageFile':'maskFile']=file;candidate.urls['images/'+file]=url;sources.set(url,surface);}
   candidate.analysis.rows=candidate.analysis.rows.map((row:any)=>replacements.get(row.id)??row);candidate.manifest.layers=candidate.manifest.layers.map((row:any)=>replacements.get(row.id)??row);
   await preview!.render(candidate,canvas.value!,()=>fail('gpu'));if(!live)return;clearTimeout(timer);inFlight=false;computing.value=!!debounce||pending;if(pending)refresh();
  }catch(e){if(live)fail((e as any).code);}
 };timer=setTimeout(()=>{worker?.terminate();fail();},30000);worker.postMessage({action:'init',rows:original.analysis.rows,ids:[...props.ids],target:props.target,assets},Object.values(assets).map((image:any)=>image.data.buffer));
 }catch(e){busy.value=false;fail((e as any).code);}});
async function apply(){if(busy.value||computing.value||inFlight||applying.value||!valid.value||error.value)return;applying.value=true;try{const result=await props.commit({kind:'distort',ids:[...props.ids],target:props.target,corners:copy()},owner);if(result.project)emit('close');else fail(result.error);}catch{fail();}finally{applying.value=false;}}
onUnmounted(()=>{live=false;worker?.terminate();preview?.dispose();clearTimeout(timer);clearTimeout(debounce);stopUndo();stopRedo();release();emit('running',false);});
</script>
<template><div class="modal-shade" @click.self="close"><section class="dialog distort-dialog" role="dialog" aria-modal="true" :aria-label="t.distort" @keydown="key"><h2>{{target==='mask'?t.distortMask:t.distort}}</h2><p>{{t.distortHint}}</p><p v-if="error" role="alert">{{error}}</p><p v-else-if="!valid" role="alert">{{t.distortInvalid}}</p>
 <svg ref="svg" class="distort-editor" data-testid="distort-editor" tabindex="0" :aria-label="t.distort" :viewBox="`${view.x} ${view.y} ${view.w} ${view.h}`" @pointerdown="start($event)" @pointermove="move" @pointerup="end" @pointercancel="end" @lostpointercapture="end" @wheel.prevent="wheel"><foreignObject x="0" y="0" :width="project.manifest.width" :height="project.manifest.height" pointer-events="none"><canvas ref="canvas" data-testid="distort-canvas" style="width:100%;height:100%"/></foreignObject><polygon v-if="valid" :points="corners.map(p=>p.join(',')).join(' ')" fill="none" stroke="#bae9d6" :stroke-width="radius/7" pointer-events="none"/><line v-for="(line,i) in grid" :key="i" :x1="line[0][0]" :y1="line[0][1]" :x2="line[1][0]" :y2="line[1][1]" stroke="#bae9d6" :stroke-width="radius/10" pointer-events="none"/><circle v-for="(corner,i) in corners" :key="i" :data-testid="'distort-handle-'+i" :cx="Number.isFinite(corner[0])?corner[0]:0" :cy="Number.isFinite(corner[1])?corner[1]:0" :r="radius" :fill="selected===i?'#b9e5d2':'#fff'" stroke="#18392b" :stroke-width="radius/5" @pointerdown.stop="start($event,i)"/></svg>
 <div class="button-row"><button :disabled="busy||applying" @click="fit">{{t.fit}}</button><label><input v-model="showGrid" type="checkbox">{{t.distortGrid}}</label><button data-testid="distort-reset" :disabled="busy||applying" @click="reset">{{t.defaults}}</button><button data-testid="distort-undo" :disabled="!past.length||applying" @click="history('undo')">{{t.distortUndo}}</button><button data-testid="distort-redo" :disabled="!future.length||applying" @click="history('redo')">{{t.distortRedo}}</button></div>
 <fieldset class="distort-coordinates" :disabled="busy||applying"><div v-for="(corner,i) in corners" :key="i"><span>{{t.distortCorners[i]}}</span><label v-for="(axis,j) in ['X','Y']" :key="axis">{{axis}}<input :data-testid="`distort-${i}-${j}`" type="number" min="-1000000" max="1000000" step=".1" :value="corner[j]" @change="coordinate(i,j,$event)"></label></div></fieldset>
 <p>{{target==='mask'?t.distortMaskNote:t.distortRasterNote}}</p><div class="button-row dialog-actions"><button :disabled="applying" @click="close">{{t.cancel}}</button><button class="primary" data-testid="distort-apply" :disabled="busy||computing||applying||!valid||!!error" @click="apply">{{applying||computing?t.loading:t.apply}}</button></div>
</section></div></template>
<style scoped>.distort-dialog{width:min(1050px,96vw);max-height:94vh;overflow:auto}.distort-editor{width:100%;height:48vh;display:block;touch-action:none;background:repeating-conic-gradient(#555 0 25%,#888 0 50%) 0/16px 16px;outline:1px solid var(--border);margin:12px 0}.distort-editor:focus{outline:2px solid var(--accent)}.distort-editor circle{cursor:crosshair}.distort-coordinates{border:0;padding:12px 0;display:grid;grid-template-columns:1fr 1fr;gap:8px}.distort-coordinates>div{display:flex;align-items:center;gap:10px}.distort-coordinates label{display:flex;align-items:center;gap:5px}.distort-coordinates input{width:90px}.distort-coordinates span{min-width:70px}</style>
